"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { getDashboardData } from "@/lib/indicators-service";
import { DashboardIndicator } from "@/lib/types";
import {
    ArrowLeft,
    Target,
    Activity,
    Shield,
    ChevronRight,
    Info
} from "lucide-react";
import {
    LineChart,
    Line,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip as RechartsTooltip,
    ResponsiveContainer,
    AreaChart,
    Area
} from "recharts";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import Link from "next/link";

export default function IndicatorDetailPage() {
    const { id } = useParams();
    const router = useRouter();
    const [indicator, setIndicator] = useState<DashboardIndicator | null>(null);
    const [allData, setAllData] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function loadData() {
            setLoading(true);
            const indicators = await getDashboardData();
            const found = indicators.find(ind => ind.id === id);

            if (found) {
                setIndicator(found);

                // Simular dados históricos se não houver muitos no Sheets ainda
                // Para uma visualização rica imediata
                const mockHistory = [
                    { month: "Jan", value: parseFloat(found.currentValue as string) || 45 },
                    { month: "Fev", value: 52 },
                    { month: "Mar", value: 48 },
                    { month: "Abr", value: 61 },
                    { month: "Mai", value: found.currentValue },
                ];
                setAllData(mockHistory);
            }
            setLoading(false);
        }
        loadData();
    }, [id]);

    if (loading) return <div className="flex h-screen items-center justify-center">Carregando detalhes...</div>;
    if (!indicator) return <div className="flex h-screen items-center justify-center text-red-500">Indicador não encontrado.</div>;

    const statusColors = {
        verde: "bg-emerald-500",
        amarelo: "bg-amber-500",
        vermelho: "bg-rose-500",
        neutro: "bg-slate-400"
    };

    const statusLabels = {
        verde: "Conforme",
        amarelo: "Atenção",
        vermelho: "Crítico",
        neutro: "Sem Dados"
    };

    return (
        <div className="min-h-screen bg-slate-50 dark:bg-zinc-950 p-4 md:p-8 font-['Exo_2',sans-serif]">
            {/* Header com Navegação */}
            <div className="max-w-7xl mx-auto mb-8">
                <button
                    onClick={() => router.back()}
                    className="flex items-center text-slate-500 hover:text-red-600 transition-colors mb-4 group"
                >
                    <ArrowLeft className="w-4 h-4 mr-2 group-hover:-translate-x-1 transition-transform" />
                    Voltar para o Dashboard
                </button>

                <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                    <div>
                        <div className="flex items-center gap-3 mb-2">
                            <Badge variant="outline" className="text-xs uppercase tracking-wider font-bold border-red-200 text-red-700 bg-red-50">
                                {indicator.id}
                            </Badge>
                            <div className={`h-2.5 w-2.5 rounded-full ${statusColors[indicator.status]}`} />
                            <span className="text-sm font-medium text-slate-500">{statusLabels[indicator.status]}</span>
                        </div>
                        <h1 className="text-3xl font-extrabold text-slate-900 dark:text-white leading-tight">
                            {indicator.nome}
                        </h1>
                    </div>

                    <div className="flex items-center gap-4 bg-white dark:bg-zinc-900 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-zinc-800">
                        <div className="text-right">
                            <p className="text-xs text-slate-500 uppercase font-bold tracking-widest">Valor Atual</p>
                            <p className="text-3xl font-black text-red-600">{indicator.currentValue}</p>
                        </div>
                        <div className="h-10 w-px bg-slate-200" />
                        <div className="text-right">
                            <p className="text-xs text-slate-500 uppercase font-bold tracking-widest">Meta</p>
                            <p className="text-lg font-bold text-slate-700 dark:text-slate-300">{indicator.meta}</p>
                        </div>
                    </div>
                </div>
            </div>

            <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Coluna Principal: Gráfico */}
                <div className="lg:col-span-2 space-y-8">
                    <Card className="shadow-xl border-none overflow-hidden bg-white dark:bg-zinc-900">
                        <CardHeader className="border-b border-slate-100 dark:border-zinc-800 pb-4">
                            <div className="flex items-center justify-between">
                                <CardTitle className="text-lg flex items-center gap-2">
                                    <Activity className="w-5 h-5 text-red-600" />
                                    Evolução do Desempenho
                                </CardTitle>
                                <div className="flex gap-2">
                                    <Badge variant="secondary">Mensal</Badge>
                                    <Badge variant="outline">2025</Badge>
                                </div>
                            </div>
                        </CardHeader>
                        <CardContent className="pt-8">
                            <div className="h-[400px] w-full">
                                <ResponsiveContainer width="100%" height="100%">
                                    <AreaChart
                                        data={allData}
                                        margin={{ top: 10, right: 10, left: 0, bottom: 0 }}
                                    >
                                        <defs>
                                            <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                                                <stop offset="5%" stopColor="#ef4444" stopOpacity={0.1} />
                                                <stop offset="95%" stopColor="#ef4444" stopOpacity={0} />
                                            </linearGradient>
                                        </defs>
                                        <CartesianGrid
                                            strokeDasharray="3 3"
                                            vertical={false}
                                            stroke="#E2E8F0"
                                        />
                                        <XAxis
                                            dataKey="month"
                                            axisLine={false}
                                            tickLine={false}
                                            tick={{ fill: '#64748B', fontSize: 12 }}
                                        />
                                        <YAxis
                                            axisLine={false}
                                            tickLine={false}
                                            tick={{ fill: '#64748B', fontSize: 12 }}
                                        />
                                        <RechartsTooltip
                                            contentStyle={{
                                                borderRadius: '12px',
                                                border: 'none',
                                                boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)',
                                                backgroundColor: 'rgba(255, 255, 255, 0.95)',
                                                backdropFilter: 'blur(8px)'
                                            }}
                                            animationDuration={200}
                                            animationEasing="ease-out"
                                        />
                                        <Area
                                            type="monotone"
                                            dataKey="value"
                                            stroke="#ef4444"
                                            strokeWidth={3}
                                            fillOpacity={1}
                                            fill="url(#colorValue)"
                                            animationDuration={1200}
                                            animationEasing="ease-in-out"
                                            isAnimationActive={true}
                                        />
                                    </AreaChart>
                                </ResponsiveContainer>
                            </div>
                        </CardContent>
                    </Card>

                    {/* Ficha Técnica Detalhada */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <Card className="border-none shadow-md bg-white dark:bg-zinc-900">
                            <CardHeader className="pb-2">
                                <CardTitle className="text-sm font-bold uppercase text-slate-500 flex items-center gap-2">
                                    <Info className="w-4 h-4" />
                                    Definição e Cálculo
                                </CardTitle>
                            </CardHeader>
                            <CardContent className="space-y-4">
                                <div>
                                    <p className="text-xs font-bold text-red-600 uppercase mb-1">Definição</p>
                                    <p className="text-sm text-slate-700 dark:text-slate-300 leading-relaxed">{indicator.definicao}</p>
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-red-600 uppercase mb-1">Fórmula</p>
                                    <code className="text-xs bg-slate-100 dark:bg-zinc-800 p-2 rounded block text-slate-900 dark:text-slate-100 font-mono">
                                        {indicator.formula}
                                    </code>
                                </div>
                            </CardContent>
                        </Card>

                        <Card className="border-none shadow-md bg-white dark:bg-zinc-900">
                            <CardHeader className="pb-2">
                                <CardTitle className="text-sm font-bold uppercase text-slate-500 flex items-center gap-2">
                                    <Shield className="w-4 h-4" />
                                    Metadados e Governança
                                </CardTitle>
                            </CardHeader>
                            <CardContent className="space-y-4">
                                <div className="flex justify-between items-center py-2 border-b border-slate-100 dark:border-zinc-800">
                                    <span className="text-xs font-bold text-slate-500 uppercase">Responsável</span>
                                    <span className="text-sm font-bold text-slate-800 dark:text-slate-200">{indicator.responsavel}</span>
                                </div>
                                <div className="flex justify-between items-center py-2 border-b border-slate-100 dark:border-zinc-800">
                                    <span className="text-xs font-bold text-slate-500 uppercase">Periodicidade</span>
                                    <span className="text-sm font-bold text-slate-800 dark:text-slate-200">{indicator.frequencia}</span>
                                </div>
                                <div className="flex justify-between items-center py-2 border-b border-slate-100 dark:border-zinc-800">
                                    <span className="text-xs font-bold text-slate-500 uppercase">Fonte</span>
                                    <span className="text-sm font-bold text-slate-800 dark:text-slate-200">{indicator.fonte}</span>
                                </div>
                                <div className="flex justify-between items-center py-2 border-b border-slate-100 dark:border-zinc-800">
                                    <span className="text-xs font-bold text-slate-500 uppercase">Linha de Base</span>
                                    <span className="text-sm font-bold text-slate-800 dark:text-slate-200">{indicator.linha_base}</span>
                                </div>
                            </CardContent>
                        </Card>
                    </div>
                </div>

                {/* Barra Lateral: Alinhamento Estratégico */}
                <div className="space-y-8">
                    <Card className="border-none shadow-xl bg-gradient-to-br from-red-600 to-red-800 text-white">
                        <CardHeader>
                            <CardTitle className="text-lg flex items-center gap-2 text-white">
                                <Target className="w-5 h-5" />
                                Alinhamento Estratégico
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-6">
                            <div>
                                <p className="text-xs font-bold text-red-200 uppercase mb-2">Objetivo Estratégico</p>
                                <p className="font-bold text-white text-lg">{indicator.objetivo}</p>
                            </div>
                            <div>
                                <p className="text-xs font-bold text-red-200 uppercase mb-2">Farol (Metas de Faixa)</p>
                                <div className="bg-white/10 rounded-xl p-4 border border-white/20">
                                    <p className="text-sm leading-relaxed whitespace-pre-line leading-7">
                                        {indicator.farol_completo}
                                    </p>
                                </div>
                            </div>
                            <div className="pt-4">
                                <Link
                                    href="/mapa-estrategico"
                                    className="flex items-center justify-between w-full bg-white text-red-700 p-3 rounded-lg font-bold text-sm hover:bg-red-50 transition-colors"
                                >
                                    Ver Mapa Estratégico
                                    <ChevronRight className="w-4 h-4" />
                                </Link>
                            </div>
                        </CardContent>
                    </Card>

                    {/* Card de Alerta de Preenchimento (Dinâmico) */}
                    {indicator.status === 'neutro' && (
                        <Card className="border-2 border-dashed border-slate-300 dark:border-zinc-700 bg-transparent">
                            <CardContent className="p-6 text-center">
                                <div className="bg-slate-100 dark:bg-zinc-800 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-500 italic font-serif">?</div>
                                <h4 className="font-bold text-slate-700 dark:text-slate-300 mb-2">Aguardando Lançamento</h4>
                                <p className="text-xs text-slate-500 mb-4">Este indicador ainda não recebeu dados reais para o período de 2025-01 na planilha.</p>
                                <Link
                                    href="https://docs.google.com/spreadsheets/d/108kfbiwwdpeV2rlZ2UqvP33F-GwGAiBkQV-hyxGBlh0/edit"
                                    target="_blank"
                                    className="text-xs font-bold text-red-600 hover:underline"
                                >
                                    Abrir Planilha de Oficiais
                                </Link>
                            </CardContent>
                        </Card>
                    )}
                </div>
            </div>
        </div>
    );
}
